WITH dc AS (
  SELECT s.id, s.eye_colour_id, s.weight_kg FROM superhero s JOIN publisher p ON s.publisher_id = p.id
  WHERE p.publisher_name LIKE 'DC Comics%' AND s.weight_kg IS NOT NULL AND s.weight_kg > 0
),
marvel_eyes AS (
  SELECT DISTINCT s.eye_colour_id FROM superhero s JOIN publisher p ON s.publisher_id = p.id
  WHERE p.publisher_name LIKE 'Marvel Comics%' AND s.eye_colour_id IS NOT NULL
)
SELECT ROUND(AVG(dc.weight_kg)::numeric, 0) AS avg_weight_kg, COUNT(*) AS n_heroes
FROM dc JOIN marvel_eyes m ON dc.eye_colour_id = m.eye_colour_id;

